async function s(t){return $fetch("/api/customers",{params:t})}async function o(t){return $fetch(`/api/customers/${t}`)}async function c(t){return $fetch("/api/customers",{method:"POST",body:t})}async function u(t,e){return $fetch(`/api/customers/${t}`,{method:"PATCH",body:e})}async function r(t){await $fetch(`/api/customers/${t}`,{method:"DELETE"})}async function n(t){return $fetch("/api/customers/lookup",{params:t})}async function a(t){return $fetch("/api/distributors/lookup",{params:t})}export{a,s as b,o as c,c as d,r as e,n as f,u};
